import React, { useState } from 'react';
import { useMessages } from '../internal/messages';
import { ChartBaseProps, ChartFrame, MARGIN, TooltipBody, linear, niceTicks, seriesColor, useFormatters, useHiddenSeries } from './core';
import { useDefaults } from '../internal/defaults';

export interface LineChartProps<Row> extends ChartBaseProps<Row> {
  /** Fill under each line. */
  area?: boolean;
  /** Stack the series (implies `area`). */
  stacked?: boolean;
  /** Smooth the lines. Default `true`. */
  curved?: boolean;
  /** Show a dot on every point (default: only the hovered one). */
  showPoints?: boolean;
  /** Start the y axis at zero. Default `true` for areas, `false` for lines. */
  zeroBaseline?: boolean;
}

export interface BarChartProps<Row> extends ChartBaseProps<Row> {
  /** Stack the series in one bar instead of side by side. */
  stacked?: boolean;
  /** Bars run left to right (good for long category names). */
  horizontal?: boolean;
}

/* ------------------------------------------------------------ geometry */

/** Monotone cubic path: smooth without overshooting the data. */
function monotonePath(pts: Array<[number, number]>) {
  if (pts.length < 3) return pts.map((p, i) => `${i ? 'L' : 'M'}${p[0]},${p[1]}`).join('');
  const n = pts.length;
  const dx = pts.slice(1).map((p, i) => p[0] - pts[i][0]);
  const slope = pts.slice(1).map((p, i) => (p[1] - pts[i][1]) / (dx[i] || 1));
  const m = pts.map((_, i) => (i === 0 ? slope[0] : i === n - 1 ? slope[n - 2] : slope[i - 1] * slope[i] <= 0 ? 0 : (slope[i - 1] + slope[i]) / 2));
  let d = `M${pts[0][0]},${pts[0][1]}`;
  for (let i = 0; i < n - 1; i++) {
    const h = dx[i] / 3;
    d += `C${pts[i][0] + h},${pts[i][1] + m[i] * h} ${pts[i + 1][0] - h},${pts[i + 1][1] - m[i + 1] * h} ${pts[i + 1][0]},${pts[i + 1][1]}`;
  }
  return d;
}
const straightPath = (pts: Array<[number, number]>) => pts.map((p, i) => `${i ? 'L' : 'M'}${p[0]},${p[1]}`).join('');

/** A bar with 4px rounded corners on its data end only, anchored square to the baseline. */
function barPath(x: number, y: number, w: number, h: number, end: 'top' | 'right' | 'bottom' | 'left', r = 4) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  if (end === 'top') return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
  if (end === 'bottom') return `M${x},${y}V${y + h - r}Q${x},${y + h} ${x + r},${y + h}H${x + w - r}Q${x + w},${y + h} ${x + w},${y + h - r}V${y}Z`;
  if (end === 'right') return `M${x},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h - r}Q${x + w},${y + h} ${x + w - r},${y + h}H${x}Z`;
  return `M${x + w},${y}H${x + r}Q${x},${y} ${x},${y + r}V${y + h - r}Q${x},${y + h} ${x + r},${y + h}H${x + w}Z`;
}

const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

/* ------------------------------------------------------------ LineChart */

/**
 * Show how something changes over time. Hover, or focus the chart and use the
 * arrow keys, to read exact values. Fill the area underneath, stack series,
 * and switch to a data table view for screen readers.
 *
 * Change over time or an
 * ordered axis. Thin 2px lines that draw in like current, a crosshair and
 * tooltip that follow the pointer, keyboard stepping (focus the chart, then
 * ← →), legend toggles, and a data-table view. One y axis only.
 *
 * Style hooks: `.sp-chart[data-kind="line"|"area"]`, `__line`, `__area`,
 * `__crosshair`, `__point`, `__grid`, `__axis`. Colours: `--spark-chart-1…8`.
 */
export function LineChart<Row>(inProps: LineChartProps<Row>) {
  const props = useDefaults('LineChart', inProps) as LineChartProps<Row>;
  const { data, x, series, height = 280, stacked = false, curved = true, showPoints = false } = props;
  const area = props.area || stacked;
  const zero = props.zeroBaseline ?? area;
  const [hidden, toggle] = useHiddenSeries();
  const [active, setActive] = useState<number | null>(null);
  const [tipX, setTipX] = useState(0);
  const f = useFormatters<Row>(props);
  const msg = useMessages();
  const visible = series.map((s, i) => ({ s, i })).filter(({ s }) => !hidden.has(s.key));

  // Stacked totals per row, bottom-up in series order.
  const stacks = data.map((row) => {
    let acc = 0;
    return visible.map(({ s }) => {
      const lo = stacked ? acc : 0;
      acc = stacked ? acc + num((row as Record<string, unknown>)[s.key]) : num((row as Record<string, unknown>)[s.key]);
      return [lo, acc] as [number, number];
    });
  });
  const values = stacks.flat().flat();
  const lo = zero ? Math.min(0, ...values) : Math.min(...values);
  const hi = Math.max(...values, lo + 1);
  const ticks = niceTicks(lo, hi);

  const render = (width: number) => {
    const iw = width - MARGIN.left - MARGIN.right;
    const ih = height - MARGIN.top - MARGIN.bottom;
    const sx = (i: number) => MARGIN.left + (data.length < 2 ? iw / 2 : (i / (data.length - 1)) * iw);
    const sy = linear(ticks[0], ticks[ticks.length - 1], MARGIN.top + ih, MARGIN.top);
    const path = curved ? monotonePath : straightPath;
    const xLabelEvery = Math.max(1, Math.ceil(data.length / Math.max(2, Math.floor(iw / 80))));

    const go = (i: number) => {
      setActive(i);
      setTipX(sx(i));
    };
    const pick = (clientX: number, rect: DOMRect) => {
      const rel = ((clientX - rect.left - MARGIN.left) / iw) * (data.length - 1);
      go(Math.max(0, Math.min(data.length - 1, Math.round(rel))));
    };

    return (
      <svg
        width={width}
        height={height}
        className="sp-chart__svg"
        role="img"
        aria-label={`${typeof props.title === 'string' ? props.title : props['aria-label'] ?? msg.chart}: ${visible.map(({ s }) => s.label).join(', ')}`}
        tabIndex={0}
        onPointerMove={(e) => pick(e.clientX, e.currentTarget.getBoundingClientRect())}
        onPointerLeave={() => setActive(null)}
        onBlur={() => setActive(null)}
        onKeyDown={(e) => {
          if (e.key === 'ArrowRight') go(Math.min(data.length - 1, (active ?? -1) + 1));
          else if (e.key === 'ArrowLeft') go(Math.max(0, (active ?? data.length) - 1));
          else if (e.key === 'Home') go(0);
          else if (e.key === 'End') go(data.length - 1);
          else if (e.key === 'Escape') setActive(null);
          else return;
          e.preventDefault();
        }}
      >
        <g className="sp-chart__grid" aria-hidden="true">
          {ticks.map((t) => (
            <g key={t}>
              <line x1={MARGIN.left} x2={MARGIN.left + iw} y1={sy(t)} y2={sy(t)} data-zero={t === 0 || undefined} />
              <text x={MARGIN.left - 8} y={sy(t)} dy="0.32em" textAnchor="end" className="sp-chart__axis">
                {f.axis(t)}
              </text>
            </g>
          ))}
          {data.map((row, i) =>
            i % xLabelEvery === 0 ? (
              <text key={i} x={sx(i)} y={height - 8} textAnchor="middle" className="sp-chart__axis">
                {f.x((row as Record<string, unknown>)[x])}
              </text>
            ) : null,
          )}
        </g>
        {visible.map(({ s, i }, vi) => {
          const top = data.map((_, r) => [sx(r), sy(stacks[r][vi][1])] as [number, number]);
          const base = data.map((_, r) => [sx(r), sy(stacks[r][vi][0])] as [number, number]);
          const color = seriesColor(series, i);
          const areaD = area ? `${path(top)}L${base[base.length - 1][0]},${base[base.length - 1][1]}${path([...base].reverse()).replace(/^M/, 'L')}Z` : '';
          return (
            <g key={s.key} aria-hidden="true">
              {area && <path d={areaD} className="sp-chart__area" style={{ fill: color }} />}
              <path d={path(top)} className="sp-chart__line" pathLength={1} style={{ stroke: color }} />
              {showPoints && top.map(([px, py], r) => <circle key={r} cx={px} cy={py} r={3} className="sp-chart__dot" style={{ fill: color }} />)}
            </g>
          );
        })}
        {active !== null && (
          <g aria-hidden="true">
            <line className="sp-chart__crosshair" x1={sx(active)} x2={sx(active)} y1={MARGIN.top} y2={MARGIN.top + ih} />
            {visible.map(({ s, i }, vi) => (
              <circle key={s.key} cx={sx(active)} cy={sy(stacks[active][vi][1])} r={4.5} className="sp-chart__point" style={{ fill: seriesColor(series, i) }} />
            ))}
          </g>
        )}
      </svg>
    );
  };

  const activeRow = active !== null ? (data[active] as Record<string, unknown>) : null;
  return (
    <ChartFrame
      {...props}
      kind={area ? 'area' : 'line'}
      hidden={hidden}
      onToggle={toggle}
      tooltipPos={active !== null ? { x: tipX, y: (props.height ?? 280) / 2 } : null}
      tooltip={
        activeRow && (
          <TooltipBody
            heading={f.x(activeRow[x])}
            rows={visible.map(({ s, i }) => ({ label: s.label, value: f.value(num(activeRow[s.key])), color: seriesColor(series, i) })).reverse()}
          />
        )
      }
      children={render}
    />
  );
}

/* ------------------------------------------------------------- BarChart */

/**
 * Compare amounts side by side, stacked or horizontally. Bars are rounded only
 * at their ends with a little gap between them, so they stay easy to read even
 * with several series.
 *
 * Compare amounts across categories. Grouped or `stacked`,
 * vertical or `horizontal`. Thin bars with 4px rounded data ends, square to
 * the baseline, a 2px gap between neighbours; a per-group tooltip on hover
 * or keyboard (focus the chart, then arrow keys), legend toggles and a
 * data-table view.
 *
 * Style hooks: `.sp-chart[data-kind="bar"]`, `__bar[data-active]`, `__band`.
 */
export function BarChart<Row>(inProps: BarChartProps<Row>) {
  const props = useDefaults('BarChart', inProps) as BarChartProps<Row>;
  const { data, x, series, height = 280, stacked = false, horizontal = false } = props;
  const [hidden, toggle] = useHiddenSeries();
  const [active, setActive] = useState<number | null>(null);
  const [tip, setTip] = useState<{ x: number; y: number } | null>(null);
  const f = useFormatters<Row>(props);
  const msg = useMessages();
  const visible = series.map((s, i) => ({ s, i })).filter(({ s }) => !hidden.has(s.key));
  const totals = data.map((row) => visible.reduce((a, { s }) => a + num((row as Record<string, unknown>)[s.key]), 0));
  const maxV = stacked ? Math.max(1, ...totals) : Math.max(1, ...data.flatMap((row) => visible.map(({ s }) => num((row as Record<string, unknown>)[s.key]))));
  const ticks = niceTicks(0, maxV);
  const labelW = horizontal ? Math.min(140, 12 + Math.max(...data.map((r) => f.x((r as Record<string, unknown>)[x]).length)) * 7) : 0;

  const render = (width: number) => {
    const m = { ...MARGIN, left: horizontal ? labelW : MARGIN.left, bottom: horizontal ? 24 : MARGIN.bottom };
    const iw = width - m.left - m.right;
    const ih = height - m.top - m.bottom;
    const n = data.length;
    const band = (horizontal ? ih : iw) / Math.max(n, 1);
    const groupPad = band * 0.22;
    const inner = band - groupPad * 2;
    const per = stacked ? inner : inner / Math.max(visible.length, 1);
    const val = linear(0, ticks[ticks.length - 1], 0, horizontal ? iw : ih);
    const gap = 2;

    const at = (clientX: number, clientY: number, rect: DOMRect) => {
      const pos = horizontal ? clientY - rect.top - m.top : clientX - rect.left - m.left;
      const i = Math.floor(pos / band);
      if (i < 0 || i >= n) return setActive(null);
      setActive(i);
      setTip(horizontal ? { x: Math.min(width - 40, m.left + val(totalsOrMax(i)) + 8), y: m.top + band * i + band / 2 } : { x: m.left + band * i + band / 2, y: m.top + ih - val(totalsOrMax(i)) });
    };
    const totalsOrMax = (i: number) => (stacked ? totals[i] : Math.max(0, ...visible.map(({ s }) => num((data[i] as Record<string, unknown>)[s.key]))));
    const xLabelEvery = horizontal ? 1 : Math.max(1, Math.ceil(n / Math.max(2, Math.floor(iw / 70))));

    return (
      <svg
        width={width}
        height={height}
        className="sp-chart__svg"
        role="img"
        aria-label={`${typeof props.title === 'string' ? props.title : props['aria-label'] ?? msg.chart}: ${visible.map(({ s }) => s.label).join(', ')}`}
        tabIndex={0}
        onPointerMove={(e) => at(e.clientX, e.clientY, e.currentTarget.getBoundingClientRect())}
        onPointerLeave={() => setActive(null)}
        onBlur={() => setActive(null)}
        onKeyDown={(e) => {
          const next = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
          if (e.key === 'Escape') setActive(null);
          else if (next) {
            const i = Math.max(0, Math.min(n - 1, (active ?? (next > 0 ? -1 : n)) + next));
            setActive(i);
            setTip(horizontal ? { x: Math.min(width - 40, m.left + val(totalsOrMax(i)) + 8), y: m.top + band * i + band / 2 } : { x: m.left + band * i + band / 2, y: m.top + ih - val(totalsOrMax(i)) });
          } else return;
          e.preventDefault();
        }}
      >
        <g className="sp-chart__grid" aria-hidden="true">
          {ticks.map((t) =>
            horizontal ? (
              <g key={t}>
                <line x1={m.left + val(t)} x2={m.left + val(t)} y1={m.top} y2={m.top + ih} data-zero={t === 0 || undefined} />
                <text x={m.left + val(t)} y={height - 6} textAnchor="middle" className="sp-chart__axis">
                  {f.axis(t)}
                </text>
              </g>
            ) : (
              <g key={t}>
                <line x1={m.left} x2={m.left + iw} y1={m.top + ih - val(t)} y2={m.top + ih - val(t)} data-zero={t === 0 || undefined} />
                <text x={m.left - 8} y={m.top + ih - val(t)} dy="0.32em" textAnchor="end" className="sp-chart__axis">
                  {f.axis(t)}
                </text>
              </g>
            ),
          )}
          {data.map((row, i) =>
            i % xLabelEvery === 0 ? (
              horizontal ? (
                <text key={i} x={m.left - 8} y={m.top + band * i + band / 2} dy="0.32em" textAnchor="end" className="sp-chart__axis sp-chart__category">
                  {f.x((row as Record<string, unknown>)[x])}
                </text>
              ) : (
                <text key={i} x={m.left + band * i + band / 2} y={height - 8} textAnchor="middle" className="sp-chart__axis">
                  {f.x((row as Record<string, unknown>)[x])}
                </text>
              )
            ) : null,
          )}
        </g>
        {active !== null && (
          <rect
            className="sp-chart__band"
            aria-hidden="true"
            x={horizontal ? m.left : m.left + band * active}
            y={horizontal ? m.top + band * active : m.top}
            width={horizontal ? iw : band}
            height={horizontal ? band : ih}
          />
        )}
        <g aria-hidden="true">
          {data.map((row, r) => {
            let acc = 0;
            return visible.map(({ s, i }, vi) => {
              const v = Math.max(0, num((row as Record<string, unknown>)[s.key]));
              const len = val(v);
              const start = stacked ? val(acc) : 0;
              acc += v;
              const isTop = !stacked || vi === visible.length - 1 || visible.slice(vi + 1).every(({ s: s2 }) => num((row as Record<string, unknown>)[s2.key]) <= 0);
              const offset = groupPad + (stacked ? 0 : per * vi);
              const thick = Math.max(1, per - (stacked ? 0 : gap));
              // In stacks, each segment gives up 2px at its far end so neighbours are separated by the surface.
              const segLen = stacked && !isTop ? Math.max(0, len - gap) : len;
              if (segLen <= 0) return null;
              const d = horizontal
                ? barPath(m.left + start, m.top + band * r + offset, segLen, thick, 'right', isTop ? 4 : 0)
                : barPath(m.left + band * r + offset, m.top + ih - start - segLen, thick, segLen, 'top', isTop ? 4 : 0);
              return <path key={s.key} d={d} className="sp-chart__bar" data-active={active === r || undefined} style={{ fill: seriesColor(series, i) }} />;
            });
          })}
        </g>
      </svg>
    );
  };

  const row = active !== null ? (data[active] as Record<string, unknown>) : null;
  return (
    <ChartFrame
      {...props}
      kind="bar"
      hidden={hidden}
      onToggle={toggle}
      tooltipPos={active !== null ? tip : null}
      tooltip={
        row && (
          <TooltipBody
            heading={f.x(row[x]) + (stacked && visible.length > 1 ? ` · ${f.value(totals[active!])}` : '')}
            rows={visible.map(({ s, i }) => ({ label: s.label, value: f.value(num(row[s.key])), color: seriesColor(series, i) }))}
          />
        )
      }
      children={render}
    />
  );
}

import React, { useId, useState } from 'react';
import { useMessages } from '../internal/messages';
import { ClassNames, slot, useDefaults } from '../internal/defaults';
import { useFormatters } from './core';

export interface DonutSlice {
  label: string;
  value: number;
  /** Default: the next categorical slot, in order. */
  color?: string;
}

export interface DonutChartProps {
  /** Parts of one whole. Keep it to 6 or fewer; fold the rest into "Other". */
  data: DonutSlice[];
  /** Heading shown above the chart, also used as its accessible name. */
  title?: React.ReactNode;
  /** Accessible name, read by screen readers. Use it when there's no visible label. */
  'aria-label'?: string;
  /** Headline in the hole. Default: the total. */
  centerLabel?: React.ReactNode;
  /** Small caption under the headline. Default "Total". */
  centerCaption?: React.ReactNode;
  /** Diameter in px. Default 200. */
  size?: number;
  /** Ring thickness in px. Default 28. */
  thickness?: number;
  /** Intl number format for values in the legend and tooltip, e.g. `{ style: 'currency', currency: 'INR' }`. */
  valueFormat?: Intl.NumberFormatOptions;
  /** Extra class names for the outermost element. */
  className?: string;
  /** Extra class names for the component's inner parts, keyed by part name. Handy with Tailwind. */
  classNames?: ClassNames<'root' | 'title' | 'legend' | 'plot'>;
}

const TAU = Math.PI * 2;
function arc(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number) {
  const p = (r: number, a: number) => `${cx + r * Math.sin(a)},${cy - r * Math.cos(a)}`;
  const big = a1 - a0 > Math.PI ? 1 : 0;
  return `M${p(r1, a0)}A${r1},${r1} 0 ${big} 1 ${p(r1, a1)}L${p(r0, a1)}A${r0},${r0} 0 ${big} 0 ${p(r0, a0)}Z`;
}

/**
 * Parts of a whole, with room for a headline number in the middle. Best with a
 * handful of slices; the legend shows values and percentages so nothing
 * depends on colour alone.
 *
 * Share of a whole. Slices start at 12 o'clock in data order,
 * separated by a 2px surface gap; the legend lists every slice with its
 * value and percentage so identity never depends on colour alone. Hover or
 * focus a slice (Tab, then ← →) for its tooltip.
 *
 * Style hooks: `.sp-chart[data-kind="donut"]`, `__slice[data-active]`, `__center`.
 */
export function DonutChart(inProps: DonutChartProps) {
  const props = useDefaults('DonutChart', inProps) as DonutChartProps;
  const m = useMessages();
  const { data, title, size = 200, thickness = 28, centerCaption = m.total, className, classNames } = props;
  const [active, setActive] = useState<number | null>(null);
  const f = useFormatters({ valueFormat: props.valueFormat });
  const titleId = useId();
  const total = data.reduce((a, d) => a + Math.max(0, d.value), 0) || 1;
  const r1 = size / 2;
  const r0 = r1 - thickness;
  const gap = 2 / r1; // 2px of surface between slices, measured on the outer edge
  const pct = (v: number) => `${Math.round((v / total) * 1000) / 10}%`;
  const color = (i: number) => data[i].color ?? `var(--spark-chart-${(i % 8) + 1})`;

  let a = 0;
  const slices = data.map((d, i) => {
    const sweep = (Math.max(0, d.value) / total) * TAU;
    const s = { a0: a + (data.length > 1 ? gap / 2 : 0), a1: a + sweep - (data.length > 1 ? gap / 2 : 0) };
    a += sweep;
    return s;
  });

  return (
    <figure className={slot('sp-chart', classNames, 'root', className)} data-kind="donut" aria-labelledby={title ? titleId : undefined} aria-label={title ? undefined : props['aria-label']}>
      {title && (
        <figcaption id={titleId} className={slot('sp-chart__title', classNames, 'title')}>
          {title}
        </figcaption>
      )}
      <div className={slot('sp-chart__donut', classNames, 'plot')}>
        <div className="sp-chart__donut-ring" style={{ width: size, height: size }}>
          <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} role="group" aria-label={typeof title === 'string' ? title : props['aria-label'] ?? m.chart}>
            {data.map((d, i) =>
              slices[i].a1 > slices[i].a0 ? (
                <path
                  key={d.label}
                  d={data.length === 1 ? arc(r1, r1, r0, r1, 0, TAU - 0.0001) : arc(r1, r1, active === i ? r0 - 2 : r0, active === i ? r1 : r1 - 2, slices[i].a0, slices[i].a1)}
                  className="sp-chart__slice"
                  data-active={active === i || undefined}
                  style={{ fill: color(i) }}
                  tabIndex={0}
                  role="img"
                  aria-label={`${d.label}: ${f.value(d.value)}, ${pct(d.value)}`}
                  onPointerEnter={() => setActive(i)}
                  onPointerLeave={() => setActive(null)}
                  onFocus={() => setActive(i)}
                  onBlur={() => setActive(null)}
                  onKeyDown={(e) => {
                    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
                    if (!step) return;
                    e.preventDefault();
                    const paths = (e.currentTarget.parentNode as SVGElement).querySelectorAll<SVGPathElement>('.sp-chart__slice');
                    paths[(Array.from(paths).indexOf(e.currentTarget) + step + paths.length) % paths.length]?.focus();
                  }}
                />
              ) : null,
            )}
          </svg>
          {/* Hover/focus readout lives in the hole; the legend row highlights too. */}
          <div className="sp-chart__center" aria-live="polite">
            {active !== null ? (
              <>
                <strong>{pct(data[active].value)}</strong>
                <span>
                  {data[active].label} · {f.value(data[active].value)}
                </span>
              </>
            ) : (
              <>
                <strong>{props.centerLabel ?? f.axis(total)}</strong>
                <span>{centerCaption}</span>
              </>
            )}
          </div>
        </div>
        <ul className={slot('sp-chart__legend sp-chart__legend--list', classNames, 'legend')}>
          {data.map((d, i) => (
            <li key={d.label} data-active={active === i || undefined}>
              <span className="sp-chart__swatch" style={{ background: color(i) }} aria-hidden="true" />
              <span className="sp-chart__legend-label">{d.label}</span>
              <span className="sp-chart__legend-value">{f.value(d.value)}</span>
              <span className="sp-chart__legend-pct">{pct(d.value)}</span>
            </li>
          ))}
        </ul>
      </div>
    </figure>
  );
}

export interface SparklineProps {
  /** Values in order (oldest first). */
  data: number[];
  /** What the line shows, for screen readers, e.g. "Sign-ups, last 30 days". */
  'aria-label': string;
  /** Width in pixels. Default 120. */
  width?: number;
  /** Height in pixels. Default 32. */
  height?: number;
  /** Fill under the line. */
  area?: boolean;
  /** Line colour. Default `--spark-chart-1`. */
  color?: string;
  /** Mark the last value with a dot. Default `true`. */
  showLast?: boolean;
  /** Extra class names for the outermost element. */
  className?: string;
}

/**
 * A tiny trend line that fits in a table cell or beside a number. No axes, no
 * fuss, just the shape of the data and, optionally, its latest value.
 *
 * A word-sized trend for tables, stat tiles and cards. No axes;
 * the last point is marked so the current value is easy to find. Its
 * accessible name states the first, last and range.
 */
export function Sparkline(inProps: SparklineProps) {
  const { data, width = 96, height = 28, area = false, color = 'var(--spark-chart-1)', showLast = true, className, ...rest } = useDefaults('Sparkline', inProps) as SparklineProps;
  const id = useId().replace(/:/g, '');
  if (!data.length) return null;
  const lo = Math.min(...data);
  const hi = Math.max(...data);
  const pad = 3;
  const sx = (i: number) => pad + (data.length < 2 ? (width - pad * 2) / 2 : (i / (data.length - 1)) * (width - pad * 2));
  const sy = (v: number) => (hi === lo ? height / 2 : pad + (1 - (v - lo) / (hi - lo)) * (height - pad * 2));
  const line = data.map((v, i) => `${i ? 'L' : 'M'}${sx(i).toFixed(1)},${sy(v).toFixed(1)}`).join('');
  const last = data[data.length - 1];
  return (
    <svg
      className={['sp-sparkline', className].filter(Boolean).join(' ')}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label={`${rest['aria-label']}: from ${data[0]} to ${last}, low ${lo}, high ${hi}`}
    >
      {area && (
        <>
          <defs>
            <linearGradient id={`sp-spark-${id}`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="0" stopColor={color} stopOpacity="0.28" />
              <stop offset="1" stopColor={color} stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={`${line}L${sx(data.length - 1)},${height}L${sx(0)},${height}Z`} fill={`url(#sp-spark-${id})`} />
        </>
      )}
      <path d={line} fill="none" stroke={color} strokeWidth={1.5} strokeLinejoin="round" strokeLinecap="round" />
      {showLast && <circle cx={sx(data.length - 1)} cy={sy(last)} r={2.5} fill={color} stroke="var(--spark-surface-base)" strokeWidth={1.5} />}
    </svg>
  );
}

import React, { useEffect, useId, useMemo, useRef, useState } from 'react';
import { useMessages } from '../internal/messages';
import { useLocale } from 'react-aria';
import { slot, ClassNames } from '../internal/defaults';

/* ------------------------------------------------------------------ types */

export interface ChartSeries<Row> {
  /** Field of each row holding this series' value. */
  key: keyof Row & string;
  /** Name in the legend, tooltip and table. */
  label: string;
  /**
   * Colour. Default: the next slot of the validated categorical palette
   * (`--spark-chart-1` … `-8`), assigned in fixed order. Colour follows the
   * series, not its position, so hiding one never repaints the others.
   */
  color?: string;
}

export interface ChartBaseProps<Row> {
  /** One object per point on the x axis, with a field for `x` and one for each series, e.g. `{ month: 'Jan', sales: 420 }`. */
  data: Row[];
  /** Field used for the category / x axis. */
  x: keyof Row & string;
  /** One or more series (up to 8; fold the rest into "Other"). */
  series: ChartSeries<Row>[];
  /** Title shown above the chart; also its accessible name. */
  title?: React.ReactNode;
  /** Accessible name when there is no visible title. */
  'aria-label'?: string;
  /** One-line summary for screen readers, e.g. "Revenue rose 40% in Q3". */
  description?: string;
  /** Height in px. Width follows the container. Default 280. */
  height?: number;
  /** Intl options for values, e.g. `{ style: 'currency', currency: 'INR', notation: 'compact' }`. */
  valueFormat?: Intl.NumberFormatOptions;
  /** Format x values for axis, tooltip and table. Default: dates by locale, others as text. */
  formatX?: (value: unknown) => string;
  /** Show the legend (default: when there are 2+ series). */
  legend?: boolean;
  /** Show a "Data table" toggle under the chart. Default `true`. */
  tableView?: boolean;
  /** Extra class names for the outermost element. */
  className?: string;
  /** Extra class names for the component's inner parts, keyed by part name. Handy with Tailwind. */
  classNames?: ClassNames<'root' | 'title' | 'legend' | 'plot' | 'tooltip' | 'table'>;
}

/* ---------------------------------------------------------------- scales */

/** Rounded ticks covering [min, max]: 0, 250, 500… or 0, 0.2, 0.4… */
export function niceTicks(min: number, max: number, count = 5): number[] {
  if (min === max) max = min + 1;
  const span = max - min;
  const raw = span / count;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= count) ?? 10 * mag;
  const start = Math.floor(min / step) * step;
  const end = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let v = start; v <= end + step / 2; v += step) ticks.push(Number(v.toFixed(10)));
  return ticks;
}

export const linear = (d0: number, d1: number, r0: number, r1: number) => (v: number) => (d1 === d0 ? r0 : r0 + ((v - d0) / (d1 - d0)) * (r1 - r0));

/* ------------------------------------------------------------------ size */

/** Width of the container, kept up to date. Starts at 600 for server rendering. */
export function useWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(600);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(([entry]) => setWidth(Math.max(120, Math.round(entry.contentRect.width))));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, width] as const;
}

/* ------------------------------------------------------------ formatting */

export function useFormatters<Row>(props: Pick<ChartBaseProps<Row>, 'valueFormat' | 'formatX'>) {
  const { locale } = useLocale();
  return useMemo(() => {
    const num = new Intl.NumberFormat(locale, props.valueFormat);
    const axisNum = new Intl.NumberFormat(locale, { notation: 'compact', maximumFractionDigits: 1, ...props.valueFormat });
    const date = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short' });
    const fx = props.formatX ?? ((v: unknown) => (v instanceof Date ? date.format(v) : String(v ?? '')));
    return { value: (v: number) => num.format(v), axis: (v: number) => axisNum.format(v), x: fx };
  }, [locale, props.valueFormat, props.formatX]);
}

/** Series colours in fixed palette order; a series keeps its colour wherever it appears. */
export const seriesColor = <Row,>(series: ChartSeries<Row>[], i: number) => series[i].color ?? `var(--spark-chart-${(i % 8) + 1})`;

/* ----------------------------------------------------------------- frame */

export interface FrameProps<Row> extends ChartBaseProps<Row> {
  kind: string;
  /** Series hidden via the legend. */
  hidden: Set<string>;
  onToggle: (key: string) => void;
  tooltip: React.ReactNode;
  tooltipPos: { x: number; y: number } | null;
  children: (width: number) => React.ReactNode;
  /** Rows/series for the table view. */
  tableColumns?: Array<{ key: string; label: string }>;
}

/**
 * Shared chart shell: title, legend (click to hide a series), responsive
 * plot, a tooltip layer and an accessible data-table view. Every chart
 * type renders inside it.
 */
export function ChartFrame<Row>({
  kind,
  data,
  x,
  series,
  title,
  'aria-label': ariaLabel,
  description,
  legend,
  tableView = true,
  valueFormat,
  formatX,
  className,
  classNames,
  hidden,
  onToggle,
  tooltip,
  tooltipPos,
  children,
  tableColumns,
}: FrameProps<Row>) {
  const [ref, width] = useWidth<HTMLDivElement>();
  const titleId = useId();
  const f = useFormatters<Row>({ valueFormat, formatX });
  const m = useMessages();
  const showLegend = legend ?? series.length > 1;
  const cols = tableColumns ?? series.map((s) => ({ key: s.key, label: s.label }));
  return (
    <figure className={slot('sp-chart', classNames, 'root', className)} data-kind={kind} aria-labelledby={title ? titleId : undefined} aria-label={title ? undefined : ariaLabel}>
      {title && (
        <figcaption id={titleId} className={slot('sp-chart__title', classNames, 'title')}>
          {title}
        </figcaption>
      )}
      {showLegend && (
        <ul className={slot('sp-chart__legend', classNames, 'legend')} aria-label={m.series}>
          {series.map((s, i) => (
            <li key={s.key}>
              <button type="button" className="sp-chart__key" aria-pressed={!hidden.has(s.key)} onClick={() => onToggle(s.key)}>
                <span className="sp-chart__swatch" style={{ background: seriesColor(series, i) }} aria-hidden="true" />
                {s.label}
              </button>
            </li>
          ))}
        </ul>
      )}
      <div ref={ref} className={slot('sp-chart__plot', classNames, 'plot')}>
        {description && <p className="sp-visually-hidden">{description}</p>}
        {children(width)}
        {tooltip && tooltipPos && (
          <div
            className={slot('sp-chart__tooltip', classNames, 'tooltip')}
            role="status"
            style={{ left: tooltipPos.x, top: tooltipPos.y, transform: `translate(${tooltipPos.x > width / 2 ? 'calc(-100% - 12px)' : '12px'}, -50%)` }}
          >
            {tooltip}
          </div>
        )}
      </div>
      {tableView && (
        <details className={slot('sp-chart__table', classNames, 'table')}>
          <summary>{m.dataTable}</summary>
          <div className="sp-chart__table-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">{String(x)}</th>
                  {cols.map((c) => (
                    <th key={c.key} scope="col">
                      {c.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.map((row, i) => (
                  <tr key={i}>
                    <th scope="row">{f.x((row as Record<string, unknown>)[x])}</th>
                    {cols.map((c) => {
                      const v = (row as Record<string, unknown>)[c.key];
                      return <td key={c.key}>{typeof v === 'number' ? f.value(v) : String(v ?? '')}</td>;
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      )}
    </figure>
  );
}

/** Legend toggling: hidden series keep their colour slot. */
export function useHiddenSeries() {
  const [hidden, setHidden] = useState<Set<string>>(new Set());
  const toggle = (key: string) =>
    setHidden((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  return [hidden, toggle] as const;
}

/** Tooltip body: heading plus a row per series with its colour key. */
export function TooltipBody({ heading, rows }: { heading: string; rows: Array<{ label: string; value: string; color: string }> }) {
  return (
    <>
      <div className="sp-chart__tooltip-heading">{heading}</div>
      {rows.map((r) => (
        <div key={r.label} className="sp-chart__tooltip-row">
          <span className="sp-chart__swatch" style={{ background: r.color }} aria-hidden="true" />
          <span className="sp-chart__tooltip-label">{r.label}</span>
          <span className="sp-chart__tooltip-value">{r.value}</span>
        </div>
      ))}
    </>
  );
}

